type D2cConfigs = {
  /**
   * Figma 访问令牌类型
   * @default "personal"
   */
  tokenType?: "personal" | "oauth";
  /**
   * 是否根据 Figma 中节点的 Auto Layout 配置，自动推断并生成相对布局样式
   * (若禁用，所有元素将使用绝对定位)
   * @default true
   */
  autoLayout?: boolean;
  /**
   * 是否过滤节点的 `data-name` 属性
   * - `true`：过滤 Figma 默认图层名（如 Frame、Group 等），并移除与同标签内 `data-component-name` 完全相同的 `data-name`
   * - `false`：保留所有原始名称
   * - `(originalName) => string`：自定义过滤函数；返回非空字符串作为最终的 `data-name`，返回空串则移除该属性
   * @default true
   */
  nameFilter?: boolean | ((originalName: string) => string);
  /**
   * 是否移除节点的 `data-node-id` 属性
   * @default true
   */
  stripNodeId?: boolean;
};
type D2iConfigs = {
  /**
   * 导出图片格式
   * @default "png"
   */
  format?: "png" | "jpg" | "svg";
  /**
   * 导出图片缩放比例
   * @default 1
   */
  scale?: number;
  /**
   * @default "personal"
   */
  tokenType?: "personal" | "oauth";
};
/**
 * 从 Figma URL 解析文件 Key 和节点 ID
 */
declare function parseFigmaUrl(url: string): {
  fileKey: string;
  nodeId: string;
};
/**
 * 将 Figma 设计稿转换为 HTML
 */
declare const figma2Html: (figmaToken: string, figmaUrl: string, configs?: D2cConfigs, params?: Record<string, string>) => Promise<string>;
/**
 * 将 Figma 设计稿转换为图片 url
 */
declare const figma2Image: (figmaToken: string, figmaUrl: string, configs?: D2iConfigs) => Promise<string>;
export { type D2cConfigs, type D2iConfigs, figma2Html, figma2Image, parseFigmaUrl };